/* 06db:0d64: prints "Div n[(R)]", infantry, tanks and artillery totals of
 * the active (bit 2) or present (bit 6) units of division div.
 */
void opeu_show_division_strength(uint8_t ds[65536], HostNotify event,
                                 uint8_t div) {
  BODY_P    info;
  uint16_t  artillery, troops, armour;
  ELEMENT_P node;
  UNIT_P    units;
  uint8_t   slot;
  uint16_t  in_reserve;
  in_reserve = GROUP_FLAGS(SIDE * 4 + div) & 1;
  troops = armour = artillery = 0;
  for (units = FIRST_UNIT(SIDE * 4 + div), slot = 0; slot < 8;
       NEXT_UNIT(units), slot++) {
    if ((UNIT_FLAGS(units) & 4) || (UNIT_FLAGS(units) & 0x40)) {
      for (node = FIRST_ELEMENT(units); node; node = NEXT_ELEMENT(node)) {
        info = BODY(node);
        switch (CATEGORY(info)) {
          case 0: troops += COUNT(info); break;
          case 1: troops += COUNT(info) * 10; break;
          case 2: troops += COUNT(info) * 5; break;
          case 3: armour += COUNT(info); break;
          case 4: artillery += COUNT(info); break;
        }
      }
    }
  }
  SET_LEFT(div * 20 + 11);
  POSITION(div * 20 + 11, 0x88);
  PRINT(FORMAT, div + 1, in_reserve ? RESERVE : NOT_RESERVE, troops, armour,
        artillery);
  SET_LEFT(0);
}

